package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class BuildingPermissionActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Building Permissions","Planning approval linked directly to the parcel.");String u=getIntent().getStringExtra("ulpin");if(u==null)u="24-GJ-GN-0001-00001";DatabaseManager m=new DatabaseManager(this);Cursor c=m.getDatabase().rawQuery("SELECT permission_number,application_date,approval_date,building_type,status FROM building_permissions WHERE ulpin=?",new String[]{u});try{if(c.moveToFirst()){LinearLayout box=utils.column(this);utils.row(box,this,"Permission",c.getString(0));utils.row(box,this,"Applied",c.getString(1));utils.row(box,this,"Approved",c.getString(2));utils.row(box,this,"Building type",c.getString(3));utils.row(box,this,"Status",c.getString(4));utils.addCard(root,box,this);}else root.addView(utils.text(this,"No building permission record in demo dataset.",14,utils.MUTED,false));}finally{c.close();}utils.setScreenContentView(this, root);}
}
